function estimateTargets(profile,weight,sessions=[]){const age=Number(profile.age),height=Number(profile.heightCm),kg=Number(weight);if(!age||age<18||age>80||!height||!kg||!profile.sexCalc)return null;const offset=profile.sexCalc==='male'?5:profile.sexCalc==='female'?-161:-78;const bmr=10*kg+6.25*height-5*age+offset;const since=new Date();since.setDate(since.getDate()-28);const logged=(sessions||[]).filter(s=>s.status==='completed'&&new Date(`${s.date}T12:00:00`)>=since).length;const trainingPerWeek=logged/4;const factor=(activityBase[profile.activityLevel]||activityBase.moderate)+Math.min(.35,trainingPerWeek*.07);const maintenance=Math.round(bmr*factor);const adjustment=profile.weightGoal==='lose'?-250:profile.weightGoal==='gain'?250:0;const floor=profile.sexCalc==='male'?1500:profile.sexCalc==='female'?1200:1350;return {bmr:Math.round(bmr),maintenance,calories:Math.max(floor,Math.round((maintenance+adjustment)/25)*25),protein:Math.round(kg*1.6),trainingPerWeek:+trainingPerWeek.toFixed(1),activityFactor:+factor.toFixed(2)}}
function isMonthlyWeightDue(entries=[]){const monthly=entries.filter(e=>(e.entryType||'monthly')==='monthly');if(!monthly.length)return true;const latest=[...monthly].sort((a,b)=>b.date.localeCompare(a.date))[0],d=new Date(`${latest.date}T12:00:00`),now=new Date();return d.getFullYear()<now.getFullYear()||d.getMonth()<now.getMonth()&&d.getFullYear()<=now.getFullYear()}
function compareWeightPace(entries=[],goal='maintain'){const ordered=[...entries].sort((a,b)=>a.date.localeCompare(b.date));if(ordered.length<2)return null;const anchor=new Date(`${ordered.at(-1).date}T12:00:00`),recentStart=new Date(anchor.getTime()-28*864e5),priorStart=new Date(anchor.getTime()-56*864e5),recent=ordered.filter(e=>new Date(`${e.date}T12:00:00`)>=recentStart),prior=ordered.filter(e=>{const d=new Date(`${e.date}T12:00:00`);return d>=priorStart&&d<recentStart});let actual,days,basis;if(recent.length>=2&&prior.length>=2){actual=recent.reduce((a,e)=>a+Number(e.weightKg),0)/recent.length-prior.reduce((a,e)=>a+Number(e.weightKg),0)/prior.length;days=28;basis='fourWeekAverage'}else{const monthly=ordered.filter(e=>(e.entryType||'monthly')==='monthly'),pair=monthly.length>=2?monthly.slice(-2):ordered.slice(-2);actual=Number(pair[1].weightKg)-Number(pair[0].weightKg);days=Math.max(1,(new Date(`${pair[1].date}T12:00:00`)-new Date(`${pair[0].date}T12:00:00`))/864e5);basis='checkIns'}const expected=(goal==='lose'?-1:goal==='gain'?1:0)*(250*days/7700),diff=actual-expected;let status;if(goal==='maintain')status=Math.abs(actual)<=.5?'Within maintenance range':actual<0?'Trending down':'Trending up';else if(Math.abs(diff)<=.5)status='Close to target pace';else if(goal==='lose')status=diff<0?'Faster loss trend':'Slower loss trend';else status=diff>0?'Faster gain trend':'Slower gain trend';return {actual,expected,days:Math.round(days),status,basis}}

